(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.CoordinateLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
const tickHost=$('#ticks');for(let n=-5;n<=5;n++){if(!n)continue;for(const axis of ['x','y']){const t=document.createElement('span');t.className='tick';t.dataset.noEquation='';t.textContent=String(n).replace('-','−');t.style.left=(axis==='x'?core.position(n,0).left:46)+'%';t.style.top=(axis==='y'?core.position(0,n).top:54)+'%';tickHost.append(t);}}
const places={'origin':'Titik berada di titik asal, pada kedua sumbu.','x-axis':'Titik berada pada sumbu mendatar; tidak termasuk kuadran.','y-axis':'Titik berada pada sumbu tegak; tidak termasuk kuadran.'};
function draw(){const x=Number($('#x-coordinate').value),y=Number($('#y-coordinate').value),pos=core.position(x,y),where=core.location(x,y);$('#x-output').value=x;$('#y-output').value=y;$('#point').style.left=pos.left+'%';$('#point').style.top=pos.top+'%';$('#horizontal-guide').style.left=Math.min(50,pos.left)+'%';$('#horizontal-guide').style.width=Math.abs(pos.left-50)+'%';$('#vertical-guide').style.left=pos.left+'%';$('#vertical-guide').style.top=Math.min(50,pos.top)+'%';$('#vertical-guide').style.height=Math.abs(pos.top-50)+'%';const description=`Dari titik asal: ${x===0?'tidak bergeser mendatar':Math.abs(x)+' satuan ke '+(x>0?'kanan':'kiri')}, lalu ${y===0?'tidak bergeser tegak':Math.abs(y)+' satuan ke '+(y>0?'atas':'bawah')}. `+(places[where]||`Titik berada di kuadran ${where}.`);$('#plane').setAttribute('aria-label',`Titik P dengan koordinat (${x}, ${y}). `+description);$('#position-feedback').textContent=description;math($('#point-equation'),`P=(${x},${y})`);}
['x','y'].forEach(axis=>$('#'+axis+'-coordinate').addEventListener('input',draw));$('#swap').addEventListener('click',()=>{const x=$('#x-coordinate').value;$('#x-coordinate').value=$('#y-coordinate').value;$('#y-coordinate').value=x;draw();});$('#reset').addEventListener('click',()=>{$('#x-coordinate').value=3;$('#y-coordinate').value=2;draw();});draw();
const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#coordinate-answer').addEventListener('submit',e=>{e.preventDefault();const raw=[$('#answer-x').value,$('#answer-y').value].map(s=>s.trim().replace(/−/g,'-').replace(',','.')),valid=raw.every(s=>/^[+-]?\d+(?:\.\d+)?$/.test(s)),ok=valid&&Number(raw[0])===-4&&Number(raw[1])===3;report(0,ok,ok?'Tepat. Koordinatnya negatif empat, lalu tiga. Kiri memberi tanda negatif pada koordinat mendatar.':valid?'Belum tepat. Periksa urutan koordinat dan arah kiri atau kanan.':'Tulis satu bilangan pada setiap kotak.');});
const questions=[
{tex:'(-2,-4)',prompt:'Di mana letak titik ini?',options:['Kuadran II','Kuadran III','Kuadran IV'],answer:1,why:'Kedua koordinat negatif: titik berada di kiri bawah, yaitu kuadran III.'},
{tex:'(0,3)',prompt:'Di mana letak titik ini?',options:['Sumbu tegak','Kuadran I','Sumbu mendatar'],answer:0,why:'Koordinat mendatar nol, sehingga titik berada pada sumbu tegak. Titik pada sumbu tidak termasuk kuadran.'},
{tex:'(4,-1)',prompt:'Ke mana bergerak dari titik asal untuk mencapai titik ini?',options:['Empat ke kiri, satu ke atas','Satu ke kanan, empat ke bawah','Empat ke kanan, satu ke bawah'],answer:2,why:'Bilangan pertama menentukan gerak mendatar; bilangan kedua menentukan gerak tegak.'},
{tex:'(2,5)\\quad\\text{dan}\\quad(2,-1)',prompt:'Apa yang sama pada kedua titik ini?',options:['Posisi mendatar','Posisi tegak','Seluruh posisinya'],answer:0,why:'Koordinat pertama sama, jadi keduanya berada pada satu garis tegak. Ketinggiannya berbeda.'},
{tex:'(0,0)',prompt:'Pernyataan mana yang benar tentang titik asal?',options:['Termasuk kuadran I','Berada pada kedua sumbu','Tidak berada pada sumbu mana pun'],answer:1,why:'Titik asal adalah perpotongan kedua sumbu dan tidak termasuk kuadran mana pun.'}
];$('#questions').innerHTML=questions.map((q,j)=>{const i=j+1;return `<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="question${i}" value="${k}">${o}</label>`).join('')}</fieldset><button class="button" data-check="${i}" type="button">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`;}).join('');document.querySelectorAll('[data-check]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.check),a=$(`[name="question${i}"]:checked`),q=questions[i-1],ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban terlebih dahulu.':ok?'Tepat. '+q.why:'Belum tepat. '+q.why);}));
const storage={get(k){try{return localStorage.getItem('fondasi-coordinate-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-coordinate-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();